diff --git a/app/Jobs/SettleSubscriptionJob.php b/app/Jobs/SettleSubscriptionJob.php
index cd3fd0c..00fa485 100755
--- a/app/Jobs/SettleSubscriptionJob.php
+++ b/app/Jobs/SettleSubscriptionJob.php
@@ -47,16 +47,27 @@ class SettleSubscriptionJob implements ShouldQueue
      */
     public function failed(): void
     {
-        Http::asJson()
+        // The ledger is the durable marker that the refund already happened.
+        // Settlement can fail after this point (for example, while pushing the
+        // cancellation), so compensation must not issue another refund.
+        if (LedgerEntry::where('subscription_id', $this->subscription->id)
+            ->where('kind', LedgerEntry::KIND_REFUND)
+            ->exists()) {
+            return;
+        }
+
+        $refund = Http::asJson()
             ->withToken((string) config('services.billinghub.key', 'test'))
             ->post('https://api.billinghub.example/v1/refunds', [
                 'subscription_id' => $this->subscription->id,
             ]);

+        $refund->throw();
+
         LedgerEntry::create([
             'subscription_id' => $this->subscription->id,
             'kind' => LedgerEntry::KIND_REFUND,
-            'amount_cents' => 9900,
+            'amount_cents' => (int) $refund->json('amount_cents'),
         ]);
     }
 }
